head.b:skin:
/* Elegant Modern CSS For Home Decor Blog */
body { font-family: 'Montserrat', 'Helvetica Neue', Helvetica, Arial, sans-serif; margin: 0; padding: 0; background-color: #F9F9F7; color: #4A4A4A; line-height: 1.7; }
header { background-color: #EBEBE6; padding: 40px 20px; text-align: center; border-bottom: 3px solid #7A8976; }
header h1 { margin: 0; color: #333333; font-size: 2.5em; text-transform: uppercase; letter-spacing: 3px; font-weight: 600; }
header p { color: #666666; font-style: italic; font-size: 1.1em; letter-spacing: 1px; margin-top: 10px; }
.container { max-width: 800px; margin: 30px auto; padding: 0 20px; }
.post { background: #FFFFFF; padding: 35px; margin-bottom: 40px; border-radius: 4px; box-shadow: 0 4px 20px rgba(0,0,0,0.03); border: 1px solid #EBEBE6; }
.post-title { font-size: 2em; margin-top: 0; color: #222222; font-weight: 600; line-height: 1.3; }
.post-title a { color: #222222; text-decoration: none; }
.post-title a:hover { color: #7A8976; }
.ad-slot { margin: 30px 0; text-align: center; overflow: hidden; }
img { max-width: 100%; height: auto; border-radius: 4px; }
a { color: #7A8976; text-decoration: none; font-weight: 500; }
a:hover { text-decoration: underline; color: #5A6956; }
.post-body { font-size: 1.1em; color: #4A4A4A; }
h2, h3, h4 { color: #333333; font-weight: 500; margin-top: 30px; }
